import { Loader2 } from 'lucide-react-native';
import * as React from 'react';
import { View } from 'react-native';

import { cn } from '@/lib/utils';

import { Icon } from './icon';
import { TextClassContext } from './text';

/**
 * The spinner that goes inside a busy Button.
 *
 * RNR's Button has no `loading` prop — the pattern is to disable it and compose
 * a spinner beside the label. Written out at each call site that meant picking
 * the spinner's colour by hand, and fifteen call sites picked
 * `text-primary-foreground` or `text-foreground` from memory. It works for every
 * variant except `destructive`, whose label is `text-white`: in dark mode
 * `--primary-foreground` is near-black, so the spinner came out invisible next
 * to a white label.
 *
 * So it takes no colour. It reads the same `TextClassContext` the Button sets
 * for its label, which makes matching the label the only thing it can do.
 */
export function ButtonSpinner({ className }: { className?: string }) {
  const textClass = React.useContext(TextClassContext);
  return (
    <View className="pointer-events-none animate-spin">
      <Icon as={Loader2} className={cn(textClass ?? 'text-foreground', className)} />
    </View>
  );
}
